249:        }
250:        if (shouldPropagate) {
251:            synchronized (mCallbacks) {
252:                for (int i = 0; i < mCallbacks.size(); i++) {
253:                    mCallbacks.get(i).onHvacPowerChange(isOn);
254:                }
255:            }
256:        }
